def r12_prev_unwrap (c : Std.Usize) (low : Std.U16) : Result Std.Usize := do
  let i ← lift (~~~ 65535#usize)
  let i1 ← lift (c &&& i)
  let i2 ← lift (UScalar.cast .Usize low)
  let q ← lift (i1 ||| i2)
  if q < c
  then ok q
  else ok (core.num.Usize.wrapping_sub q 65536#usize)
